package dev.capebridge.proxy;
import dev.capebridge.common.TextCatalog;
import java.util.*;
final class Messages {
 private static volatile TextCatalog current=TextFiles.defaults("messages.yml");
 private static final List<Map.Entry<String,String>> ERRORS=List.of(Map.entry("cape.image.dimensions","errors.cape-image-dimensions"),Map.entry("cape.animation.dimensions","errors.cape-animation-dimensions"),Map.entry("cape.animation.timing","errors.cape-animation-timing"),Map.entry("Official cape atlas required: 64x32, 128x64, ... up to 512x256; old 5:8 front artwork must be converted","errors.official-cape-atlas-required-64x32-128x64-up-to-512x256-old-5-8-f"),Map.entry("sync-secret must contain at least 32 characters","errors.sync-secret-must-contain-at-least-32-characters"),Map.entry("add <id> <file.png> / addblock <id> <MATERIAL>","errors.add-id-file-png-addblock-id-material"),Map.entry("Resource ID must be lowercase a-z, 0-9, _ or -","errors.resource-id-must-be-lowercase-a-z-0-9-or"),Map.entry("set <player|UUID> <id> / clear <player|UUID>","errors.set-player-uuid-id-clear-player-uuid"),Map.entry("PNG must be a regular file, not a link","errors.png-must-be-a-regular-file-not-a-link"),Map.entry("PNG must be directly inside capes/","errors.png-must-be-directly-inside-capes"),Map.entry("Path outside plugin data directory","errors.path-outside-plugin-data-directory"),Map.entry("Link escapes plugin data directory","errors.link-escapes-plugin-data-directory"),Map.entry("Symbolic links are not permitted","errors.symbolic-links-are-not-permitted"),Map.entry("Cannot initialize CapeBridge","errors.cannot-initialize-capebridge"),Map.entry("Invalid cape configuration: ","errors.invalid-cape-configuration"),Map.entry("CustomModelData collision: ","errors.custommodeldata-collision"),Map.entry("Unknown command; use bcape","errors.unknown-command-use-bcape"),Map.entry("Plugin is shutting down","errors.plugin-is-shutting-down"),Map.entry("Duplicate model ID: ","errors.duplicate-model-id"),Map.entry("PNG must be <= 1 MiB","errors.png-must-be-1-mib"),Map.entry("Invalid cape type: ","errors.invalid-cape-type"),Map.entry("Invalid public-url","errors.invalid-public-url"),Map.entry("Invalid material","errors.invalid-material"),Map.entry("Player needs ","errors.player-needs"),Map.entry("Unknown cape","errors.unknown-cape"),Map.entry("PNG required","errors.png-required"),Map.entry("Invalid PNG","errors.invalid-png"),Map.entry("Maximum ","errors.maximum"));
 static void use(TextCatalog next){current=next;}
 static String t(String key,Object...args){return current.text(key,args);}
 static String raw(String key,Object...args){return current.raw(key,args);}
 static void send(net.md_5.bungee.api.CommandSender sender,String key,Object...args){for(String line:current.lines(key,args)){sender.sendMessage(net.md_5.bungee.api.chat.TextComponent.fromLegacyText(line));}}
 static String error(Throwable error){String value=error.getMessage()==null?error.getClass().getSimpleName():error.getMessage();for(var e:ERRORS)if(value.startsWith(e.getKey()))return t(e.getValue(),"detail",value.substring(e.getKey().length()));return t("errors.unexpected","detail",value);}
}
